import itertools

def greedy_algorithm(N):
    coins = [25, 10, 1]
    count = 0
    for coin in coins:
        while N >= coin:
            N -= coin
            count += 1
    return count

def is_greedy_successful(N):
    for i in range(1, N+1):
        if greedy_algorithm(i) > i:
            return False
    return True

def count_greedy_successful_values(N):
    return sum(is_greedy_successful(i) for i in range(1, N+1))

N = 1000
print(count_greedy_successful_values(N))

